<voice name='研究所長' class='研究所長' src='voice/ma04/013vs2050b22'>
//「欠陥じゃねぇぇよ！
//　<RUBY text='バッテリー'>燃料缶</RUBY>交換してやりゃあ済むわ！」
"It's not defective! You just need to switch out the batteries!"

pt:
//【研究所長】
<voice name='研究所長' class='研究所長' src='voice/ma04/013vs2050b22'>
//「欠陥じゃねぇぇよ！
//　<RUBY text='バッテリー'>燃料缶</RUBY>交換してやりゃあ済むわ！」
